-- 세트 579. 여러 번 실행해도 안전하다 (NOT EXISTS 가드). 원본: 02_quest_set.sql, 03_quest_set579.sql, 05·06·08. docs/specs/spec_pilot_gap_sets.md
INSERT INTO quest_set (id, title, description, sandbox_type, category)
SELECT 579, '파일시스템 장애 상황집: 슈퍼블록 손상 복구, 종류 식별, fsck 출력 읽기', '"마운트가 안 된다 / bad superblock" 같은 파일시스템 장애를 이미지 파일로 재현해 복구해 보는 상황집입니다. 슈퍼블록이 망가진 ext4 를 백업 슈퍼블록으로 되살리고, 데이터를 꺼내 확인하고, 종류를 모르는 디스크가 실제로 무엇인지 식별하고, fsck 가 남긴 출력에서 손상된 항목을 읽습니다. 마운트 권한이 없어 이미지 파일에서 진행합니다.', 'linux', '스토리지'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest_set WHERE id = 579);
UPDATE quest_set SET display_order = 839, unit_id = (SELECT id FROM unit WHERE id = 71), icon = '🛟' WHERE id = 579;

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 579, 1, '오류 메시지 확인', '`/tmp/broken.img` 는 마운트하려고 하면 "bad superblock" 오류가 나는 ext4 이미지입니다. 파일시스템 정보를 읽는 `dumpe2fs -h /tmp/broken.img` 를 실행해 **오류 메시지의 핵심 문구**(`Bad magic number` 가 포함된 줄)를 `/tmp/err.txt` 에 저장하세요. (오류는 표준 에러로 나옵니다)', '`dumpe2fs` 는 오류를 표준 에러로 출력합니다. 에러 출력까지 파이프로 넘겨 원하는 줄만 고르세요.', 'dumpe2fs -h /tmp/broken.img 2>&1 | head -5
dumpe2fs -h /tmp/broken.img 2>&1 | grep ''Bad magic'' > /tmp/err.txt
cat /tmp/err.txt

# 슈퍼블록(파일시스템의 크기·상태가 적힌 첫 구조)이 읽히지 않는 상태다. 슈퍼블록은 여러 곳에 백업이 있어서 복구할 수 있다', '["sh", "-c", "rm -f /tmp/*.img /tmp/*.txt /tmp/*.log /tmp/payload /tmp/restored.dat\\ndd if=/dev/urandom of=/tmp/payload bs=1k count=256 2>/dev/null\\ntruncate -s 16M /tmp/broken.img\\nmke2fs -q -F -t ext4 -b 1024 /tmp/broken.img\\ndebugfs -w -R \\"write /tmp/payload keep.dat\\" /tmp/broken.img >/dev/null 2>&1\\ndd if=/dev/zero of=/tmp/broken.img bs=1k seek=1 count=1 conv=notrunc 2>/dev/null\\ndd if=/dev/zero of=/tmp/mystery.img bs=1M count=4 2>/dev/null\\nchmod 600 /tmp/mystery.img; mkswap /tmp/mystery.img >/dev/null 2>&1\\ncat > /tmp/fsck_sample.log <<''EOF''\\nPass 1: Checking inodes, blocks, and sizes\\nInode 12 has illegal block(s).  Clear? yes\\n\\nIllegal block #3 (4294967295) in inode 12.  CLEARED.\\nInode 12, i_blocks is 40, should be 16.  Fix? yes\\n\\nInode 15 has illegal block(s).  Clear? yes\\n\\nPass 2: Checking directory structure\\nEntry ''a.dat'' in <2> (2) has deleted/unused inode 20.  Clear? yes\\n\\nPass 3: Checking directory connectivity\\nPass 4: Checking reference counts\\nPass 5: Checking group summary information\\nFree blocks count wrong for group #0 (7000, counted=6990).\\nFix? yes\\n\\n/dev/vg0/data: ***** FILE SYSTEM WAS MODIFIED *****\\n/dev/vg0/data: 120/4096 files (0.0% non-contiguous), 2700/16384 blocks\\nEOF\\ntrue"]', '["sh", "-c", "( grep -q \\"Bad magic number\\" /tmp/err.txt )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "Bad magic number 가 들어 있다", "cmd": ["sh", "-c", "grep -q \\"Bad magic number\\" /tmp/err.txt"]}]', '[{"title": "e2fsck 매뉴얼", "url": "https://man7.org/linux/man-pages/man8/e2fsck.8.html"}, {"title": "debugfs 매뉴얼", "url": "https://man7.org/linux/man-pages/man8/debugfs.8.html"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 579 AND order_index = 1);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 579, 2, '백업 슈퍼블록 위치 찾기', '슈퍼블록은 파일시스템의 여러 블록 그룹에 백업이 있습니다. 같은 크기·블록 크기(1024)로 파일시스템을 **새로 만든다면** 백업이 어디에 놓일지 알려 주는 **모의 실행** 옵션이 있습니다(실제로 쓰지 않습니다). 이 이미지의 **첫 번째 백업 슈퍼블록 블록 번호**를 `/tmp/backup_sb.txt` 에 저장하세요. (숫자만) 주의: 모의 실행 옵션 없이 파일시스템 생성 도구를 실행하면 내용이 지워집니다.', '파일시스템 생성 도구에는 "실제로 만들지 않고 결과만 보여 주는" 옵션이 있습니다. 블록 크기를 같게 줘야 위치가 같습니다.', 'mke2fs -n -b 1024 /tmp/broken.img 2>&1 | tail -4
mke2fs -n -b 1024 /tmp/broken.img 2>&1 | grep -A1 ''Superblock backups'' | tail -1 | awk ''{print $1}'' | tr -d '','' > /tmp/backup_sb.txt
cat /tmp/backup_sb.txt

# 주의: -n 없이 mke2fs 를 실행하면 파일시스템이 새로 만들어져 데이터가 사라진다. 반드시 -n 을 확인한다', '["sh", "-c", "rm -f /tmp/*.img /tmp/*.txt /tmp/*.log /tmp/payload /tmp/restored.dat\\ndd if=/dev/urandom of=/tmp/payload bs=1k count=256 2>/dev/null\\ntruncate -s 16M /tmp/broken.img\\nmke2fs -q -F -t ext4 -b 1024 /tmp/broken.img\\ndebugfs -w -R \\"write /tmp/payload keep.dat\\" /tmp/broken.img >/dev/null 2>&1\\ndd if=/dev/zero of=/tmp/broken.img bs=1k seek=1 count=1 conv=notrunc 2>/dev/null\\ndd if=/dev/zero of=/tmp/mystery.img bs=1M count=4 2>/dev/null\\nchmod 600 /tmp/mystery.img; mkswap /tmp/mystery.img >/dev/null 2>&1\\ncat > /tmp/fsck_sample.log <<''EOF''\\nPass 1: Checking inodes, blocks, and sizes\\nInode 12 has illegal block(s).  Clear? yes\\n\\nIllegal block #3 (4294967295) in inode 12.  CLEARED.\\nInode 12, i_blocks is 40, should be 16.  Fix? yes\\n\\nInode 15 has illegal block(s).  Clear? yes\\n\\nPass 2: Checking directory structure\\nEntry ''a.dat'' in <2> (2) has deleted/unused inode 20.  Clear? yes\\n\\nPass 3: Checking directory connectivity\\nPass 4: Checking reference counts\\nPass 5: Checking group summary information\\nFree blocks count wrong for group #0 (7000, counted=6990).\\nFix? yes\\n\\n/dev/vg0/data: ***** FILE SYSTEM WAS MODIFIED *****\\n/dev/vg0/data: 120/4096 files (0.0% non-contiguous), 2700/16384 blocks\\nEOF\\ntrue"]', '["sh", "-c", "( [ \\"$(cat /tmp/backup_sb.txt)\\" = 8193 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "8193 이다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/backup_sb.txt)\\" = 8193 ]"]}]', '[{"title": "e2fsck 매뉴얼", "url": "https://man7.org/linux/man-pages/man8/e2fsck.8.html"}, {"title": "debugfs 매뉴얼", "url": "https://man7.org/linux/man-pages/man8/debugfs.8.html"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 579 AND order_index = 2);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 579, 3, '백업 슈퍼블록으로 복구', '앞에서 찾은 **백업 슈퍼블록**을 써서 `/tmp/broken.img` 를 복구하세요. 질문에는 모두 yes 로 답하고, 복구 뒤 **점검에서 오류가 없어야** 하며 안에 있던 `keep.dat` 도 살아 있어야 합니다.', '파일시스템 점검 도구에 대체 슈퍼블록을 지정하는 옵션이 있습니다. 질문에 자동으로 답하는 옵션도 함께 쓰세요.', 'e2fsck -b 8193 -y /tmp/broken.img
e2fsck -fn /tmp/broken.img
debugfs -R ''ls -l'' /tmp/broken.img | grep keep.dat

# -b 를 안 줘도 e2fsck 가 백업을 자동으로 시도하는 경우가 있다. 실제 디스크에서는 먼저 dd 로 통째 복사본을 만들어 두고 복사본에서 시도하는 것이 안전하다. 복구가 잘못되면 더 망가질 수 있다', '["sh", "-c", "rm -f /tmp/*.img /tmp/*.txt /tmp/*.log /tmp/payload /tmp/restored.dat\\ndd if=/dev/urandom of=/tmp/payload bs=1k count=256 2>/dev/null\\ntruncate -s 16M /tmp/broken.img\\nmke2fs -q -F -t ext4 -b 1024 /tmp/broken.img\\ndebugfs -w -R \\"write /tmp/payload keep.dat\\" /tmp/broken.img >/dev/null 2>&1\\ndd if=/dev/zero of=/tmp/broken.img bs=1k seek=1 count=1 conv=notrunc 2>/dev/null\\ndd if=/dev/zero of=/tmp/mystery.img bs=1M count=4 2>/dev/null\\nchmod 600 /tmp/mystery.img; mkswap /tmp/mystery.img >/dev/null 2>&1\\ncat > /tmp/fsck_sample.log <<''EOF''\\nPass 1: Checking inodes, blocks, and sizes\\nInode 12 has illegal block(s).  Clear? yes\\n\\nIllegal block #3 (4294967295) in inode 12.  CLEARED.\\nInode 12, i_blocks is 40, should be 16.  Fix? yes\\n\\nInode 15 has illegal block(s).  Clear? yes\\n\\nPass 2: Checking directory structure\\nEntry ''a.dat'' in <2> (2) has deleted/unused inode 20.  Clear? yes\\n\\nPass 3: Checking directory connectivity\\nPass 4: Checking reference counts\\nPass 5: Checking group summary information\\nFree blocks count wrong for group #0 (7000, counted=6990).\\nFix? yes\\n\\n/dev/vg0/data: ***** FILE SYSTEM WAS MODIFIED *****\\n/dev/vg0/data: 120/4096 files (0.0% non-contiguous), 2700/16384 blocks\\nEOF\\ntrue"]', '["sh", "-c", "( e2fsck -fn /tmp/broken.img >/dev/null 2>&1 ) && ( debugfs -R \\"ls -l\\" /tmp/broken.img 2>/dev/null | grep -q keep.dat )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "점검 결과가 깨끗하다", "cmd": ["sh", "-c", "e2fsck -fn /tmp/broken.img >/dev/null 2>&1"]}, {"label": "keep.dat 가 있다", "cmd": ["sh", "-c", "debugfs -R \\"ls -l\\" /tmp/broken.img 2>/dev/null | grep -q keep.dat"]}]', '[{"title": "e2fsck 매뉴얼", "url": "https://man7.org/linux/man-pages/man8/e2fsck.8.html"}, {"title": "debugfs 매뉴얼", "url": "https://man7.org/linux/man-pages/man8/debugfs.8.html"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 579 AND order_index = 3);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 579, 4, '복구한 데이터 꺼내 검증', '(앞 문제에서 복구를 마친 상태입니다) `/tmp/broken.img` 에서 `keep.dat` 파일을 꺼내 `/tmp/restored.dat` 로 저장하세요. 마운트하지 못하므로 파일시스템 디버깅 도구로 파일을 직접 꺼냅니다. 원본(`/tmp/payload`)과 내용이 같아야 합니다.', '`debugfs` 에는 파일시스템 안의 파일을 바깥으로 꺼내는 명령이 있습니다. `-R` 로 명령 하나를 실행할 수 있습니다.', 'debugfs -R ''dump keep.dat /tmp/restored.dat'' /tmp/broken.img
cmp /tmp/restored.dat /tmp/payload && echo same

# 마운트가 안 되는 파일시스템에서도 debugfs 로 파일을 꺼낼 수 있어 복구 전 데이터부터 구출할 때 쓴다. 복구 후에는 반드시 내용을 원본과 대조한다', '["sh", "-c", "rm -f /tmp/*.img /tmp/*.txt /tmp/*.log /tmp/payload /tmp/restored.dat\\ndd if=/dev/urandom of=/tmp/payload bs=1k count=256 2>/dev/null\\ntruncate -s 16M /tmp/broken.img\\nmke2fs -q -F -t ext4 -b 1024 /tmp/broken.img\\ndebugfs -w -R \\"write /tmp/payload keep.dat\\" /tmp/broken.img >/dev/null 2>&1\\ndd if=/dev/zero of=/tmp/broken.img bs=1k seek=1 count=1 conv=notrunc 2>/dev/null\\ndd if=/dev/zero of=/tmp/mystery.img bs=1M count=4 2>/dev/null\\nchmod 600 /tmp/mystery.img; mkswap /tmp/mystery.img >/dev/null 2>&1\\ncat > /tmp/fsck_sample.log <<''EOF''\\nPass 1: Checking inodes, blocks, and sizes\\nInode 12 has illegal block(s).  Clear? yes\\n\\nIllegal block #3 (4294967295) in inode 12.  CLEARED.\\nInode 12, i_blocks is 40, should be 16.  Fix? yes\\n\\nInode 15 has illegal block(s).  Clear? yes\\n\\nPass 2: Checking directory structure\\nEntry ''a.dat'' in <2> (2) has deleted/unused inode 20.  Clear? yes\\n\\nPass 3: Checking directory connectivity\\nPass 4: Checking reference counts\\nPass 5: Checking group summary information\\nFree blocks count wrong for group #0 (7000, counted=6990).\\nFix? yes\\n\\n/dev/vg0/data: ***** FILE SYSTEM WAS MODIFIED *****\\n/dev/vg0/data: 120/4096 files (0.0% non-contiguous), 2700/16384 blocks\\nEOF\\ne2fsck -b 8193 -y /tmp/broken.img >/dev/null 2>&1\\ntrue"]', '["sh", "-c", "( cmp -s /tmp/restored.dat /tmp/payload )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "원본과 같다", "cmd": ["sh", "-c", "cmp -s /tmp/restored.dat /tmp/payload"]}]', '[{"title": "e2fsck 매뉴얼", "url": "https://man7.org/linux/man-pages/man8/e2fsck.8.html"}, {"title": "debugfs 매뉴얼", "url": "https://man7.org/linux/man-pages/man8/debugfs.8.html"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 579 AND order_index = 4);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 579, 5, '정체를 모르는 디스크 식별', '`/tmp/mystery.img` 를 `mount -t ext4` 로 마운트하려니 "wrong fs type" 오류가 났다고 합니다. 이 이미지의 **실제 파일시스템(또는 영역) 종류**를 식별해 종류 이름만 `/tmp/type.txt` 에 저장하세요.', '블록 장치(이미지)의 내용을 보고 종류를 알려 주는 도구가 있습니다. 필요한 속성만 출력하는 옵션이 있습니다.', 'blkid /tmp/mystery.img
blkid -s TYPE -o value /tmp/mystery.img > /tmp/type.txt
cat /tmp/type.txt

# swap 영역은 파일시스템이 아니라 마운트가 안 된다. 같은 증상이어도 종류를 먼저 확인한다. mkfs 를 다시 하기 전에 내용이 정말 필요 없는지부터 확인한다', '["sh", "-c", "rm -f /tmp/*.img /tmp/*.txt /tmp/*.log /tmp/payload /tmp/restored.dat\\ndd if=/dev/urandom of=/tmp/payload bs=1k count=256 2>/dev/null\\ntruncate -s 16M /tmp/broken.img\\nmke2fs -q -F -t ext4 -b 1024 /tmp/broken.img\\ndebugfs -w -R \\"write /tmp/payload keep.dat\\" /tmp/broken.img >/dev/null 2>&1\\ndd if=/dev/zero of=/tmp/broken.img bs=1k seek=1 count=1 conv=notrunc 2>/dev/null\\ndd if=/dev/zero of=/tmp/mystery.img bs=1M count=4 2>/dev/null\\nchmod 600 /tmp/mystery.img; mkswap /tmp/mystery.img >/dev/null 2>&1\\ncat > /tmp/fsck_sample.log <<''EOF''\\nPass 1: Checking inodes, blocks, and sizes\\nInode 12 has illegal block(s).  Clear? yes\\n\\nIllegal block #3 (4294967295) in inode 12.  CLEARED.\\nInode 12, i_blocks is 40, should be 16.  Fix? yes\\n\\nInode 15 has illegal block(s).  Clear? yes\\n\\nPass 2: Checking directory structure\\nEntry ''a.dat'' in <2> (2) has deleted/unused inode 20.  Clear? yes\\n\\nPass 3: Checking directory connectivity\\nPass 4: Checking reference counts\\nPass 5: Checking group summary information\\nFree blocks count wrong for group #0 (7000, counted=6990).\\nFix? yes\\n\\n/dev/vg0/data: ***** FILE SYSTEM WAS MODIFIED *****\\n/dev/vg0/data: 120/4096 files (0.0% non-contiguous), 2700/16384 blocks\\nEOF\\ntrue"]', '["sh", "-c", "( [ \\"$(cat /tmp/type.txt)\\" = swap ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "swap 이다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/type.txt)\\" = swap ]"]}]', '[{"title": "e2fsck 매뉴얼", "url": "https://man7.org/linux/man-pages/man8/e2fsck.8.html"}, {"title": "debugfs 매뉴얼", "url": "https://man7.org/linux/man-pages/man8/debugfs.8.html"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 579 AND order_index = 5);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 579, 6, 'fsck 출력에서 손상된 inode', '`/tmp/fsck_sample.log` 는 어떤 서버에서 `e2fsck` 를 수정 모드로 실행한 출력입니다. `Pass 1` 에서 **"has illegal block(s)"** 로 보고된 inode 번호를 **작은 번호부터 한 줄에 하나씩** `/tmp/bad_inodes.txt` 에 저장하세요.', '손상 보고 문구가 들어간 줄에서 inode 번호가 몇 번째 칸인지 확인하세요.', 'cat /tmp/fsck_sample.log
grep ''has illegal block'' /tmp/fsck_sample.log | awk ''{print $2}'' | sort -n > /tmp/bad_inodes.txt
cat /tmp/bad_inodes.txt

# 12 와 15 번 inode 의 블록 정보가 잘못되어 지웠다. 해당 파일의 내용은 일부 잃었을 수 있어 fsck 후 lost+found 와 데이터를 확인한다', '["sh", "-c", "rm -f /tmp/*.img /tmp/*.txt /tmp/*.log /tmp/payload /tmp/restored.dat\\ndd if=/dev/urandom of=/tmp/payload bs=1k count=256 2>/dev/null\\ntruncate -s 16M /tmp/broken.img\\nmke2fs -q -F -t ext4 -b 1024 /tmp/broken.img\\ndebugfs -w -R \\"write /tmp/payload keep.dat\\" /tmp/broken.img >/dev/null 2>&1\\ndd if=/dev/zero of=/tmp/broken.img bs=1k seek=1 count=1 conv=notrunc 2>/dev/null\\ndd if=/dev/zero of=/tmp/mystery.img bs=1M count=4 2>/dev/null\\nchmod 600 /tmp/mystery.img; mkswap /tmp/mystery.img >/dev/null 2>&1\\ncat > /tmp/fsck_sample.log <<''EOF''\\nPass 1: Checking inodes, blocks, and sizes\\nInode 12 has illegal block(s).  Clear? yes\\n\\nIllegal block #3 (4294967295) in inode 12.  CLEARED.\\nInode 12, i_blocks is 40, should be 16.  Fix? yes\\n\\nInode 15 has illegal block(s).  Clear? yes\\n\\nPass 2: Checking directory structure\\nEntry ''a.dat'' in <2> (2) has deleted/unused inode 20.  Clear? yes\\n\\nPass 3: Checking directory connectivity\\nPass 4: Checking reference counts\\nPass 5: Checking group summary information\\nFree blocks count wrong for group #0 (7000, counted=6990).\\nFix? yes\\n\\n/dev/vg0/data: ***** FILE SYSTEM WAS MODIFIED *****\\n/dev/vg0/data: 120/4096 files (0.0% non-contiguous), 2700/16384 blocks\\nEOF\\ntrue"]', '["sh", "-c", "( [ \\"$(tr \\"\\\\n\\" \\" \\" < /tmp/bad_inodes.txt | xargs)\\" = \\"12 15\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "12, 15 이다", "cmd": ["sh", "-c", "[ \\"$(tr \\"\\\\n\\" \\" \\" < /tmp/bad_inodes.txt | xargs)\\" = \\"12 15\\" ]"]}]', '[{"title": "e2fsck 매뉴얼", "url": "https://man7.org/linux/man-pages/man8/e2fsck.8.html"}, {"title": "debugfs 매뉴얼", "url": "https://man7.org/linux/man-pages/man8/debugfs.8.html"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 579 AND order_index = 6);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 579, 7, '읽기 전용으로 바뀐 파일시스템', '운영 중이던 서버의 데이터 디스크가 갑자기 `Read-only file system` 오류를 냅니다. 마운트 옵션에 `errors=remount-ro` 가 있습니다. 이 상황으로 가장 알맞은 해석은?', '이 옵션이 오류를 만났을 때 하는 일을 생각해 보세요.', NULL, NULL, '[]', 'choice', '["디스크가 가득 차서 쓰기가 막혔다", "파일 권한 설정이 읽기 전용으로 바뀌었다", "오류를 감지해 읽기 전용으로 전환됐다", "서버가 곧 재부팅되는 중이다"]', 2, '`errors=remount-ro` 는 파일시스템 오류(디스크 I/O 오류 포함)를 만나면 더 이상 손상되지 않도록 읽기 전용으로 바꿉니다. dmesg 로 원인을 보고, 언마운트 후 fsck 로 점검한 뒤 다시 마운트합니다. 디스크 가득 참은 다른 오류 메시지(No space left)입니다.', NULL, NULL, NULL, NULL
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 579 AND order_index = 7);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 579, 8, '마운트 중인 파일시스템에 fsck', '운영 중인 서버에서 마운트된 ext4 파일시스템에 바로 `e2fsck -y` 를 실행하면 안 되는 이유로 가장 알맞은 것은?', '점검하는 도구와 운영 중인 시스템이 같은 구조를 동시에 바꾸면 어떻게 될지 생각해 보세요.', NULL, NULL, '[]', 'choice', '["fsck 는 읽기만 하므로 디스크 수명이 줄기 때문이다", "커널이 쓰고 있는 구조와 점검 도구가 서로 충돌해 오히려 손상될 수 있다", "마운트된 파일시스템은 fsck 가 지원하지 않는 문법을 쓰기 때문이다", "점검 결과가 항상 거짓이기 때문이다"]', 1, '마운트된 파일시스템은 커널이 계속 메타데이터를 바꿉니다. 그 위에서 수정 모드 fsck 를 실행하면 두 쪽이 동시에 같은 구조를 바꿔 손상될 수 있어 언마운트(또는 읽기 전용) 상태에서 점검해야 합니다. 읽기 전용 점검(-n)은 참고용으로만 씁니다.', NULL, NULL, NULL, NULL
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 579 AND order_index = 8);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 579, 9, '백업 슈퍼블록 지정 옵션', '슈퍼블록이 손상된 파일시스템을 **블록 8193 의 백업 슈퍼블록**으로 점검·복구하려 합니다. 빈칸에 들어갈 `e2fsck` 옵션을 채우세요.', '대체 슈퍼블록 위치를 지정하는 옵션입니다. 블록 크기를 지정하는 옵션과 헷갈리지 마세요.', NULL, NULL, '[]', 'fill', '["b", "B", "c", "l"]', NULL, '`-b` 는 사용할 슈퍼블록(백업) 위치를 지정합니다. `-B` 는 슈퍼블록을 찾을 때 쓸 블록 크기, `-c` 는 불량 블록 검사, `-l` 은 불량 블록 목록 파일 지정입니다.', '[0]', 'e2fsck -{0} 8193 /dev/sdb1', NULL, NULL
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 579 AND order_index = 9);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 579, 10, '손상된 파일시스템 복구 순서', '데이터 디스크의 파일시스템이 손상되어 복구해야 합니다. 데이터를 더 잃지 않도록 하는 순서로 놓으세요. (복사본은 언마운트한 상태에서 떠야 일관성이 있습니다.)', '수정은 가장 위험한 단계입니다.', NULL, NULL, '[]', 'order', '["읽기 전용(`-n`)으로 점검해 문제 범위를 본다", "수정 모드로 fsck 를 실행한다", "디스크를 통째로 이미지로 복사해 둔다", "파일시스템을 언마운트한다", "마운트해 데이터가 정상인지 확인한다"]', NULL, '점검·수리는 마운트를 해제한 상태에서 하고, 고치기 전에 복사본을 만들어 되돌릴 수 있게 합니다. 읽기 전용 점검으로 범위를 본 뒤 수정 모드로 실행하고, 마지막으로 마운트해 데이터를 확인합니다.', '[3, 2, 0, 1, 4]', NULL, NULL, NULL
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 579 AND order_index = 10);
